using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Assert - verify the response is not empty
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
        var responseText = response.Messages[^1].Text ?? string.Empty;
        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText));
    }

    [TestMethod]
    public async Task Chat_EvaluateRelevance()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what photosynthesis is in one sentence.")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Messages[^1].Text ?? string.Empty;

        // Evaluate relevance using the AI evaluation framework
        var evaluator = new RelevancyEvaluator();
        var result = await evaluator.EvaluateAsync(
            messages,
            new ChatResponse([new ChatMessage(ChatRole.Assistant, responseText)]),
            _chatClient);

        // Assert evaluation passes
        Assert.IsNotNull(result);
    }

    [TestMethod]
    public async Task Chat_EvaluateCoherence()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "List three benefits of exercise.")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Messages[^1].Text ?? string.Empty;

        // Evaluate coherence
        var evaluator = new CoherenceEvaluator();
        var result = await evaluator.EvaluateAsync(
            messages,
            new ChatResponse([new ChatMessage(ChatRole.Assistant, responseText)]),
            _chatClient);

        // Assert evaluation passes
        Assert.IsNotNull(result);
    }
}

